// A four-bar house pattern whose fills run "a few times" rather than a fixed
// number. `repeat 2 to 6 { … }` is the piece saying how long the figure may
// run and leaving the rest to the performance — the same sentence a DJ writes
// as "loop until the cue lands" and a folk singer writes as "as many verses as
// there are".
//
// The count is chosen once, at compile time, from the realization
// (`musa check examples/loop-lengths.musa --seed 42`). Everything below that
// choice is an ordinary exact repeat, which is why the kernel gains nothing
// from this file: see docs/kernel/11-realization.md.
piece "Loop Lengths" {
    composer "musa";

    tempo 1/4 = 124;
    meter 4/4;
    key a minor;

    score {
        part drums {
            voice kick {
                repeat 4 {
                    c2 1/4;
                    c2 1/4;
                    c2 1/4;
                    c2 1/4;
                }
                repeat 2 to 6 {
                    c2 1/4;
                    c2 1/4;
                    c2 1/8;
                    c2 1/8;
                    c2 1/4;
                }
            }

            voice hats {
                repeat 4 {
                    rest 1/8;
                    f#3 1/8;
                    rest 1/8;
                    f#3 1/8;
                    rest 1/8;
                    f#3 1/8;
                    rest 1/8;
                    f#3 1/8;
                }
                repeat 2 to 6 {
                    f#3 1/8;
                    f#3 1/8;
                    f#3 1/8;
                    f#3 1/8;
                    f#3 1/8;
                    f#3 1/8;
                    f#3 1/8;
                    f#3 1/8;
                }
            }
        }

        part bass {
            voice line {
                repeat 4 {
                    a1 1/2;
                    e2 1/4;
                    g1 1/4;
                }
                repeat 2 to 6 {
                    a1 1/4;
                    a1 1/4;
                    c2 1/4;
                    e2 1/4;
                }
            }
        }
    }
}
